      if (s.tipo === 'titulo') { const h = primero ? 'h1' : 'h2'; primero = false; return `<section class="blk lp-t"${ed(opt, 'p:secciones:secciones.' + s._i + '.x')}><${h}>${esc(s.x)}</${h}></section>`; }
